#!/bin/sh
# T143: the Neo Geo core's benches under Verilator (neo_top with the vendored chip models and cores/neogeo/fix, the DDR2 model, images of generated bytes from mkimg.py):
# no BIOS, no game. A mode ends with PASS or FAIL lines.
#   sh cores/neogeo/sim/run.sh [mode ...]        default: mover video p68k
#   pixw        (T143) tb_pixw.v: neo_pixw alone, every pixel of the frame buffer rows in its place
#   pad         (T156) tb_pad.v: the application's pad registers into the joystick words
#   mover       neo_mem alone against the DDR2 model: the image mover, the copy engine with its masks (also above 64 MB), every channel, the backup RAM client, the picture word
#   video       the picture out of an ideal DDR2 (FAST) and out of one with the board's latency (+LATMIN/+LATRND: 22 / 30 ui clocks = 293 to 693 ns) is the same after the same number of
#               MACHINE clocks (+MCYC: a held machine needs more time; compared after the same time it is still booting and the pictures are not comparable)
#   p68k        every 68k read of the system ROM and the cartridge program equals the image byte
#   lat         the latency run alone, its counters printed (S2: the stall counters tell how often the machine had to wait)
#   dl          the same for the deadlines 0, 8, 12
#   speed       dense scene (96 sprites of 14 tiles per line), board latency: >= 95 % of the machine's speed and the ideal picture
#   mover       (also) the line caches of neo_mem: hints, demands, flush, the 68k's next line
#   audio       the Z80 plays SSG channel A from an M1 image (mkimg.py --z80tone): the YM2610's mix and the host's samples move
set -e
here=$(cd "$(dirname "$0")" && pwd)
root=$(cd "$here/../../.." && pwd)
n=$root/cores/neogeo
r=$n/rtl
b=$here/build
mkdir -p "$b"
# the Z80: GHDL turns T80pa into Verilog (as tools/zx_gen.sh does for the Spectrum's); `do` is a SystemVerilog keyword
if [ ! -f "$b/t80pa.v" ]; then
  d=$(mktemp -d)
  for f in T80_Pack T80_Reg T80_MCode T80_ALU T80 T80pa; do cp "$r/cpu/T80/$f.vhd" "$d/"; done
  (cd "$d" && ghdl -a --std=08 -frelaxed -fsynopsys T80_Pack.vhd T80_Reg.vhd T80_MCode.vhd T80_ALU.vhd T80.vhd T80pa.vhd 2>/dev/null && ghdl --synth --std=08 -frelaxed -fsynopsys --out=verilog T80pa > t80pa.v 2>/dev/null)
  perl -pi -e 's/\\do /do_/g; s/\bdo\b/do_/g' "$d/t80pa.v"
  cp "$d/t80pa.v" "$b/t80pa.v"; rm -rf "$d"
fi
fixed=$(ls "$n"/fix/*.v | xargs -n1 basename | tr '\n' ' ')
vend=""
for f in $r/cells/*.v $r/io/*.v $r/io/*.sv $r/video/*.v $r/cpu/cpu_68k.v $r/cpu/cpu_z80.v $r/cpu/FX68K/*.sv $r/jt12/hdl/*.v $r/jt12/hdl/adpcm/*.v $r/jt12/hdl/mixer/*.v $r/jt49/hdl/*.v; do
  bn=$(basename "$f")
  case "$bn" in pcm.v) continue;; esac
  case " $fixed " in *" $bn "*) continue;; esac
  vend="$vend $f"
done
src="$here/tb_neo.v $here/neo_ddr2.v $here/neo_clk48_sim.v $(ls $n/trx/*.v | grep -v neo_clk48.v | tr '\n' ' ') $n/fix/*.v $b/t80pa.v $vend"
cp "$r/cpu/FX68K/microrom.mem" "$r/cpu/FX68K/nanorom.mem" "$b/" 2>/dev/null || true
build() { # build <dir> [verilator options]
  d=$1; shift
  mkdir -p "$d"
  lock=${TRX64_SIM_BUILD_LOCK:-${TMPDIR:-/tmp}/trx64-verilator-build.lock}
  until mkdir "$lock" 2>/dev/null; do
    op=$(cat "$lock/pid" 2>/dev/null || true)
    if [ -n "$op" ] && ! kill -0 "$op" 2>/dev/null; then rm -rf "$lock"; fi
    sleep 2
  done
  echo $$ > "$lock/pid"
  trap 'rm -rf "$lock"' EXIT INT TERM
  if [ ! -x "$d/Vtb_neo" ] || [ -n "$NEO_REBUILD" ]; then
    # shellcheck disable=SC2086
    nice -n 15 verilator --binary --timing -Wno-fatal -Wno-lint -Wno-style -Wno-TIMESCALEMOD -Wno-MULTIDRIVEN -Wno-BLKANDNBLK -Wno-IMPLICIT -Wno-PINMISSING --no-assert --no-assert-case -j 2 --top-module tb_neo \
      -Mdir "$d" --x-assign 0 --x-initial 0 "$@" $NEO_VDEFS $src > "$d/build.log" 2>&1 || { tail -30 "$d/build.log"; echo "FAIL build"; exit 1; }
  fi
  rm -rf "$lock"; trap - EXIT INT TERM
}
img() { # img <name> [mkimg options]
  nm=$1; shift
  python3 "$here/mkimg.py" "$b/$nm" "$@" > /dev/null
  echo "$b/$nm"
}
base=${NEO_OBJ:-$b/obj}
sim() { # sim <binary dir> <log name> <args...>
  bd=$1; ln=$2; shift 2
  (cd "$b" && "$bd/Vtb_neo" "$@" > "$b/$ln.log" 2>&1) || true
}
verdict() { grep -E "^(PASS|FAIL|  |HASH)" "$b/$1.log" | grep -v "^- " || true; }
hashof() { sed -n 's/^HASH //p' "$b/$1.log" | tail -1; }
modes=${*:-"mover video p68k"}
rc=0
for m in $modes; do
  case $m in
    mover)
      mkdir -p "$b/obj_mover"
      if [ ! -x "$b/obj_mover/Vtb_mover" ] || [ -n "$NEO_REBUILD" ]; then
        nice -n 15 verilator --binary --timing -Wno-fatal -Wno-lint -Wno-style -Wno-TIMESCALEMOD --no-assert -j 2 --top-module tb_mover -Mdir "$b/obj_mover" --x-assign 0 --x-initial 0 \
          "$here/tb_mover.v" "$here/neo_ddr2.v" "$n/trx/neo_mem.v" "$n/trx/neo_lc.v" > "$b/obj_mover/build.log" 2>&1 || { tail -30 "$b/obj_mover/build.log"; echo "FAIL build"; exit 1; }
      fi
      (cd "$b" && "$b/obj_mover/Vtb_mover" > "$b/mover.log" 2>&1) || true
      grep -E "^(PASS|FAIL|  )" "$b/mover.log" || true
      grep -q "^PASS mover" "$b/mover.log" || rc=1 ;;
    speed)
      # S7: with the hints the machine is not held at the board's DDR2 latency: 96 sprites of 14 tiles on every line (mkimg.py --dense), the same picture from an ideal memory,
      # and the machine runs at 95 % of its speed or more (before the hints: 42 %)
      build "$base"
      i=$(img img_dense --dense)
      sim "$base" sp_fast +MODE=video +DIR="$i" +MS=4000 +MCYC=${NEO_SMCYC:-20000000} +FAST &
      sim "$base" sp_lat +MODE=video +DIR="$i" +MS=4000 +MCYC=${NEO_SMCYC:-20000000} &
      wait
      h1=$(hashof sp_fast); h2=$(hashof sp_lat)
      pct=$(sed -n 's/.*ran at \([0-9]*\)\..*/\1/p' "$b/sp_lat.log" | tail -1)
      echo "speed: $(grep -E 'machine speed' "$b/sp_lat.log" | tr -s ' ')"; grep -E "^    (sprites|fix|68k)|^             " "$b/sp_lat.log" | tr -s ' ' | tr '\n' ';'; echo
      if [ -n "$h1" ] && [ "$h1" = "$h2" ] && [ -n "$pct" ] && [ "$pct" -ge 95 ]; then echo "PASS speed: the dense scene runs at $pct % of the machine's speed behind the board's DDR2 latency, the picture is the ideal one ($h1)"; else echo "FAIL speed: ideal $h1 latency $h2, speed '$pct' %"; rc=1; fi ;;
    real)
      # a real game on the real BIOS (NEO_ROMS=<dir with sp-s2.sp1, sfix.sfix, 000-lo.lo and mslug/201-*>, never in the repository): the machine boots in both layouts of
      # tools/neogeo_layout.py (mister = what the core was written for, app = what neoset.cc writes) and a frame is dumped every NEO_RDUMP machine clocks
      build "$base"
      for lay in ${NEO_RLAYOUTS:-mister app}; do
        python3 "$root/tools/neogeo_layout.py" image --roms "${NEO_ROMS:?NEO_ROMS}" --layout "$lay" --out "$b/real_$lay" > /dev/null
        mkdir -p "$b/real_$lay/frames"
        sim "$base" real_$lay +MODE=video +DIR="$b/real_$lay" +REAL +FAST +MS=100000 +MCYC=${NEO_RMCYC:-300000000} +DUMPEVERY=${NEO_RDUMP:-20000000} +DUMPDIR="$b/real_$lay/frames" &
      done
      wait
      for lay in ${NEO_RLAYOUTS:-mister app}; do echo "real $lay: $(grep -c 'dumped' "$b/real_$lay.log") frames in $b/real_$lay/frames"; done ;;
    sprites)
      # S10 (T143): the sprite path end to end against a pixel oracle. A generated sprite scene (mkimg.py --dense --sheet: 19 sprites side by side, 14 consecutive tiles each, nothing overlaps) over a
      # C ROM of generated tile art (tools/neogeo_sprites.py gen) that went through MiSTer's loader (tools/neogeo_layout.py overlay). tools/neogeo_sprites.py check computes the expected picture from the
      # art, the palette and the colour formula alone and compares every pixel of the frame the machine drew: with MiSTer's layout at the board's DDR2 latency (line caches, hints) and from an ideal memory it
      # has to be 100 %.
      build "$base"
      rm -rf "$b/spr"; mkdir -p "$b/spr"
      python3 "$root/tools/neogeo_sprites.py" selftest > /dev/null
      python3 "$root/tools/neogeo_sprites.py" gen --out "$b/spr/art" --tile-base 0x100
      for v in mister_lat:mister:0 mister_fast:mister:1; do
        nm=${v%%:*}; r=${v#*:}; lay=${r%%:*}; fast=${r#*:}
        python3 "$here/mkimg.py" "$b/spr/$nm" --dense --sheet --tile-base 0x100 > /dev/null
        python3 "$root/tools/neogeo_layout.py" overlay --roms "$b/spr/art" --layout "$lay" --out "$b/spr/$nm" > /dev/null
        fl=""; [ "$fast" = 1 ] && fl="+FAST"
        sim "$base" spr_$nm +MODE=video +DIR="$b/spr/$nm" +REAL $fl +CSTART=3 +MS=4000 +MCYC=${NEO_SPMCYC:-30000000} +DUMP="$b/spr/$nm/frame.txt" &
      done
      wait
      for nm in mister_lat mister_fast; do
        out=$(python3 "$root/tools/neogeo_sprites.py" check --dir "$b/spr/art" --pal "$b/spr/$nm/pal.txt" "$b/spr/$nm/frame.txt" 2>&1) && echo "PASS sprites $nm: $out" || { echo "FAIL sprites $nm: $out"; rc=1; }
      done ;;
    realtiles)
      # the generated machine (mkimg.py --dense: 96 sprites of 14 consecutive tiles on every line) over the REAL C ROM of NEO_ROMS in both layouts: with MiSTer's layout the sprites
      # are art (columns of one sprite sheet), with the layout neoset.cc wrote before the fix noise. A frame is dumped at the end ($b/rt_<layout>/frame_000.txt; tools/neogeo_layout.py png).
      build "$base"
      for lay in ${NEO_RLAYOUTS:-mister app}; do
        python3 "$here/mkimg.py" "$b/rt_$lay" --dense --tile-base ${NEO_TILEBASE:-0x2000} > /dev/null
        python3 "$root/tools/neogeo_layout.py" overlay --roms "${NEO_ROMS:?NEO_ROMS}" --layout "$lay" --out "$b/rt_$lay" > /dev/null
        mkdir -p "$b/rt_$lay/frames"
        sim "$base" rt_$lay +MODE=video +DIR="$b/rt_$lay" +REAL +FAST +CSTART=3 +MS=4000 +MCYC=${NEO_RTMCYC:-30000000} +DUMP="$b/rt_$lay/frame_000.txt" &
      done
      wait
      for lay in ${NEO_RLAYOUTS:-mister app}; do echo "realtiles $lay: $(grep -E 'video:' "$b/rt_$lay.log" | tr -s ' ')"; done ;;
    video)
      build "$base"
      i=$(img img)
      sim "$base" video_fast +MODE=video +DIR="$i" +MS=4000 +MCYC=30000000 +FAST &
      sim "$base" video_lat +MODE=video +DIR="$i" +MS=4000 +MCYC=30000000 &
      wait
      verdict video_fast; verdict video_lat
      h1=$(hashof video_fast); h2=$(hashof video_lat)
      if [ -n "$h1" ] && [ "$h1" = "$h2" ] && grep -q "^PASS video" "$b/video_fast.log" && grep -q "^PASS video" "$b/video_lat.log"; then echo "PASS video: the picture is the same behind the board's DDR2 latency ($h1)"; else echo "FAIL video: fast $h1 latency $h2"; rc=1; fi ;;
    lat)
      build "$base"
      i=$(img img)
      sim "$base" lat +MODE=video +DIR="$i" +MS=320
      verdict lat ;;
    dl)
      # S2: a word is handed to the machine at a fixed machine age (neo_mux.v), so the picture after the same number of MACHINE clocks must not depend on the memory: for each deadline
      # an ideal DDR2 (FAST) and the board's latency (+LATMIN/+LATRND) give one hash. NEO_DLS lists the deadlines (default 1 4 8: a stall that freezes the machine at some other ages (0, 3, 6, 9) changes the picture even with an ideal memory, see §5 of T143), NEO_MCYC the machine clocks (default 30 M).
      build "$base"
      i=$(img img)
      lat="+LATMIN=${NEO_LATMIN:-22} +LATRND=${NEO_LATRND:-30}"
      mc="+MS=4000 +MCYC=${NEO_MCYC:-30000000}"
      dls=${NEO_DLS:-1 4 8}
      for d in $dls; do
        # shellcheck disable=SC2086
        sim "$base" dl_fast_$d +MODE=video +DIR="$i" $mc +CDL=$d +SDL=$d +FAST &
        # shellcheck disable=SC2086
        sim "$base" dl_lat_$d +MODE=video +DIR="$i" $mc +CDL=$d +SDL=$d $lat &
      done
      wait
      for d in $dls; do
        h1=$(hashof dl_fast_$d); h2=$(hashof dl_lat_$d)
        if [ -n "$h1" ] && [ "$h1" = "$h2" ]; then echo "PASS dl $d: the same picture from an ideal and from the board's memory ($h1)  $(grep -E 'hand-over' "$b/dl_lat_$d.log" | tr -s ' ')  $(grep -E 'stall clocks' "$b/dl_lat_$d.log" | tr -s ' ')"; else echo "FAIL dl $d: ideal $h1 latency $h2"; rc=1; fi
      done ;;
    buildonly) build "$base" ;;
    audio)
      # the Z80 runs a program from the M1 space that switches SSG channel A on (mkimg.py --z80tone): the YM2610's mix and the host's samples must move
      build "$base"
      i=$(img img_tone --z80tone)
      sim "$base" audio +MODE=audio +DIR="$i" +MS=${NEO_AMS:-150} ${NEO_AFAST:-+FAST}
      grep -E "^(PASS|FAIL|  )" "$b/audio.log" || true
      grep -q "^PASS audio" "$b/audio.log" || rc=1 ;;
    p68k)
      build "$base"
      i=$(img img)
      sim "$base" p68k +MODE=p68k +DIR="$i" +MS=4000 +MCYC=${NEO_PMCYC:-12000000}
      verdict p68k; grep -q "^PASS p68k" "$b/p68k.log" || rc=1 ;;
    pad)
      # T156: tb_pad.v (iverilog): neo_regs PAD1/PAD2 through neo_pad into the machine's two joystick words, eleven buttons on both players, OR, commit, swap
      mkdir -p "$b/pad"
      pm() { # pm <name> [-D...]: build and run tb_pad.v
        nm=$1; shift
        iverilog -g2012 "$@" -o "$b/pad/$nm.vvp" "$here/tb_pad.v" "$n/trx/neo_regs.v" "$n/trx/neo_pad.v" || return 2
        vvp -n "$b/pad/$nm.vvp" > "$b/pad/$nm.log" 2>&1 || true
      }
      pm real
      if grep -q "^PASS tb_neo_pad" "$b/pad/real.log"; then echo "PASS pad: $(grep checks "$b/pad/real.log" | tr -s ' ')"; else cat "$b/pad/real.log"; echo "FAIL pad"; rc=1; fi ;;
    pixw)
      # T143 (sprite stripes, board 2026-10-31): tb_pixw.v (iverilog): neo_pixw alone, a frame of known pixels in, the 128 bit words out put back together, every pixel of every row compared
      mkdir -p "$b/pixw"
      iverilog -g2012 -o "$b/pixw/real.vvp" "$here/tb_pixw.v" "$n/trx/neo_pixw.v" || { echo "FAIL pixw: build"; rc=1; continue; }
      vvp -n "$b/pixw/real.vvp" > "$b/pixw/real.log" 2>&1 || true
      if grep -q "^PASS pixw" "$b/pixw/real.log"; then echo "PASS pixw: $(grep '^PASS pixw' "$b/pixw/real.log" | cut -d: -f2-)"; else cat "$b/pixw/real.log"; echo "FAIL pixw"; rc=1; fi ;;
    *) echo "unknown mode $m"; rc=2 ;;
  esac
done
exit $rc
